/**
 * Defines a single route entry by mapping a URL path pattern to a render
 * function. Parameters are inferred from the pattern and passed as the first
 * arg to the render function; the second argument is ExtensionContextValue.
 *
 * Path patterns support the following segment types:
 *
 *   /customers              — static segment, matches literally
 *   /customers/:id          — required param, matches one segment (e.g. "cus_123")
 *   /customers/:action?     — optional param, matches one segment or nothing
 *   /files/*                — wildcard, captures all remaining segments
 *   /files/*?               — optional wildcard, matches zero or more trailing segments
 *
 * Segments may be combined: /orgs/:orgId/members/:memberId
 *
 * Paths must start with "/" and may not contain empty segments ("//").
 * Parameter names must use alphanumeric characters and underscores.
 *
 * @see https://docs.stripe.com/stripe-apps/routing
 */
export function route(path, render) {
    return { path, render };
}
